const agents = [
  {name:'Ana',role:'Enfermeira',trait:'Solidária, mas desconfiada',color:'#61f5b5',x:24,y:38,memory:'Chegou à Vila Aurora buscando um recomeço.'},
  {name:'Carlos',role:'Comerciante',trait:'Pragmático e competitivo',color:'#ffc45c',x:35,y:35,memory:'O mercado é o projeto de sua vida.'},
  {name:'Lia',role:'Professora',trait:'Curiosa e conciliadora',color:'#8cb8ff',x:57,y:29,memory:'Acredita que informação muda comunidades.'},
  {name:'Ravi',role:'Técnico',trait:'Inventivo e reservado',color:'#cf93ff',x:72,y:40,memory:'Conserta tudo, mas evita falar do passado.'},
  {name:'Joana',role:'Prefeita',trait:'Ambiciosa e estratégica',color:'#ff756f',x:66,y:60,memory:'Prometeu tornar a cidade autossuficiente.'},
  {name:'Davi',role:'Jornalista',trait:'Persistente e impulsivo',color:'#ff9c69',x:44,y:63,memory:'Procura uma história que prove seu valor.'},
  {name:'Maya',role:'Agricultora',trait:'Calma e observadora',color:'#b8df6b',x:19,y:65,memory:'Conhece os ciclos da terra melhor que as pessoas.'},
  {name:'Tomás',role:'Estudante',trait:'Idealista e sociável',color:'#62dbe8',x:81,y:70,memory:'Quer descobrir quem pode se tornar.'}
];
const state={day:1,period:'Manhã',metrics:{trust:61,economy:54,tension:28},agents};
const periods=['Manhã','Tarde','Noite']; let periodIndex=0; let tick=0;
const layer=document.querySelector('#agentsLayer');

function renderAgents(){layer.innerHTML='';agents.forEach((a,i)=>{const el=document.createElement('button');el.className='agent';el.style.setProperty('--agent',a.color);el.style.left=a.x+'%';el.style.top=a.y+'%';el.dataset.name=a.name;el.textContent=a.name[0];el.onclick=()=>openAgent(a);layer.appendChild(el)})}
function openAgent(a){document.querySelector('#drawerAvatar').textContent=a.name[0];document.querySelector('#drawerAvatar').style.background=a.color;document.querySelector('#drawerName').textContent=a.name;document.querySelector('#drawerRole').textContent=a.role;document.querySelector('#drawerTrait').textContent=a.trait;document.querySelector('#drawerMemory').textContent=a.memory;document.querySelector('#agentDrawer').classList.add('open')}
document.querySelector('#closeDrawer').onclick=()=>document.querySelector('#agentDrawer').classList.remove('open');
function clamp(n){return Math.max(0,Math.min(100,n))}
function updateMetrics(delta={}){for(const key of ['trust','economy','tension']){state.metrics[key]=clamp(state.metrics[key]+(delta[key]||0));document.querySelector('#'+key+'Value').textContent=state.metrics[key]+'%';document.querySelector('#'+key+'Bar').value=state.metrics[key]}}
function addTimeline(result){const item=document.createElement('article');item.className='timeline-item';item.innerHTML=`<small>DIA ${String(state.day).padStart(2,'0')} · ${state.period.toUpperCase()}</small><h4>${result.headline}</h4><p>${result.summary}</p>`;document.querySelector('#timeline').prepend(item)}
function advanceTime(){periodIndex=(periodIndex+1)%3;if(periodIndex===0)state.day++;state.period=periods[periodIndex];document.querySelector('#day').textContent='DIA '+String(state.day).padStart(2,'0');document.querySelector('#period').textContent=['08:20','14:10','21:35'][periodIndex]+' · '+state.period.toUpperCase();agents.forEach(a=>{a.x=clamp(a.x+(Math.random()*18-9));a.y=clamp(a.y+(Math.random()*16-8))});renderAgents()}
function browserFallback(event){const actor=agents[Math.floor(Math.random()*agents.length)];const options=[['Uma aliança improvável começa a surgir','decidiu reunir vizinhos para compartilhar informações'],['A cidade se divide diante de uma escolha','questionou publicamente a primeira resposta da prefeitura'],['Um gesto pequeno muda o clima da cidade','ofereceu ajuda a alguém com quem raramente conversava']];const [headline,action]=options[Math.floor(Math.random()*options.length)];return{headline,summary:`Após “${event}”, ${actor.name} ${action}.`,actor:actor.name,memory:`${actor.name} reagiu quando ${event.toLowerCase()}.`,metric_delta:{trust:Math.floor(Math.random()*7)-2,economy:Math.floor(Math.random()*5)-2,tension:Math.floor(Math.random()*7)-2},source:'Simulação pública · abra localmente para usar o Llama'}}
async function simulate(event){const button=document.querySelector('#injectBtn');button.disabled=true;button.textContent='Pensando…';let result;try{const res=await fetch('/api/step',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state,event})});if(!res.ok)throw new Error('API indisponível');result=await res.json()}catch(e){result=browserFallback(event)}finally{button.disabled=false;button.textContent='Introduzir'}document.querySelector('#eventTitle').textContent=result.headline;document.querySelector('#eventSummary').textContent=result.summary;document.querySelector('#eventSource').textContent=result.source;const actor=agents.find(a=>a.name===result.actor);if(actor)actor.memory=result.memory;updateMetrics(result.metric_delta);addTimeline(result);advanceTime()}
document.querySelector('#injectBtn').onclick=()=>{const input=document.querySelector('#eventInput');simulate(input.value.trim()||'A cidade atravessa um dia comum');input.value=''};
document.querySelector('#eventInput').onkeydown=e=>{if(e.key==='Enter')document.querySelector('#injectBtn').click()};
document.querySelectorAll('.chips button').forEach(b=>b.onclick=()=>document.querySelector('#eventInput').value=b.dataset.event);
document.querySelector('#forkBtn').onclick=()=>{const result={headline:'Universo OR-02 criado',summary:`A linha do tempo foi bifurcada no dia ${state.day}. As próximas decisões poderão ser comparadas.`};addTimeline(result);document.querySelector('#eventTitle').textContent=result.headline;document.querySelector('#eventSummary').textContent=result.summary;document.querySelector('#eventSource').textContent='Snapshot local da simulação'};
document.querySelector('#pauseBtn').onclick=e=>{e.currentTarget.textContent=e.currentTarget.textContent.includes('Pausar')?'▶  Continuar':'Ⅱ   Pausar'};
async function checkStatus(){try{const s=await fetch('/api/status').then(r=>r.json());const el=document.querySelector('#modelStatus');el.classList.toggle('connected',s.connected);el.querySelector('span').textContent=s.connected?`Llama conectado · ${s.model}`:'Modo demonstrativo'}catch{document.querySelector('#modelStatus span').textContent='Modo demonstrativo'}}
renderAgents();updateMetrics();addTimeline({headline:'A cidade desperta',summary:'Oito habitantes iniciam suas rotinas e formam as primeiras memórias.'});checkStatus();
